insert into public.schools (slug, name, short_name, tagline, description, icon, primary_attribute, sort_order) values
  ('faith-scripture-wisdom', 'Faith, Scripture & Wisdom', 'Faith & Wisdom', 'Root your ascent in timeless truth.', 'Study the Scriptures, the history of the faith and the practice of wisdom, building a foundation of character that every other discipline rests upon.', 'book-open', 'wisdom', 0),
  ('technology-computers-ai', 'Technology, Computers & AI', 'Technology & AI', 'Understand the machines that shape the age.', 'From how computers work to writing software and understanding artificial intelligence, learn to build with technology rather than merely use it.', 'cpu', 'intellect', 1),
  ('business-entrepreneurship-finance', 'Business, Entrepreneurship & Finance', 'Business & Finance', 'Steward resources and build enduring ventures.', 'Learn how businesses create value, how to start and grow a venture, and how to manage money with wisdom and discipline.', 'briefcase', 'strategy', 2),
  ('strategy-critical-thinking', 'Strategy & Critical Thinking', 'Strategy & Thinking', 'Think clearly. Decide wisely. Act deliberately.', 'Sharpen reasoning, recognise bias and fallacy, and learn the strategic frameworks used by leaders, generals and great thinkers.', 'brain', 'strategy', 3),
  ('music-creative-arts', 'Music & Creative Arts', 'Music & Arts', 'Create beauty with skill and purpose.', 'Develop musicianship, understand theory and composition, and explore the creative arts as disciplines of both craft and expression.', 'music', 'creativity', 4),
  ('languages-communication', 'Languages & Communication', 'Languages & Communication', 'Speak, write and persuade with clarity.', 'Master your own language, learn new ones and develop the speaking, writing and listening skills that open doors.', 'languages', 'eloquence', 5),
  ('history-culture-philosophy', 'History, Culture & Philosophy', 'History & Philosophy', 'Learn from those who climbed before you.', 'Survey the great civilisations, ideas and turning points of history, and engage with the philosophers who shaped how we think.', 'landmark', 'wisdom', 6),
  ('personal-development-human-skills', 'Personal Development & Human Skills', 'Personal Development', 'Become the person your goals require.', 'Build habits, manage time and energy, lead others and develop the emotional and relational skills that make knowledge useful.', 'sprout', 'discipline', 7);
